const maps={world:{name:'World Tour',size:40,cities:['Dublin','Lisbon','Barcelona','Paris','London','Amsterdam','Rome','Berlin','Prague','Vienna','Athens','Istanbul','Cairo','Cape Town','Dubai','Mumbai','Bangkok','Singapore','Seoul','Tokyo','Sydney','Auckland','Vancouver','New York','Mexico City','Rio','Buenos Aires','Toronto']},europe:{name:'Grand Europe',size:48,cities:['Dublin','Cork','Edinburgh','London','Bath','Lisbon','Porto','Madrid','Barcelona','Paris','Lyon','Nice','Brussels','Amsterdam','Copenhagen','Oslo','Stockholm','Helsinki','Berlin','Munich','Prague','Vienna','Budapest','Venice','Florence','Rome','Naples','Athens','Split','Dubrovnik','Zurich','Geneva','Krakow','Warsaw','Tallinn','Reykjavik']},mega:{name:'Global Empire',size:64,cities:['Dublin','Lisbon','Porto','Madrid','Barcelona','Paris','London','Amsterdam','Copenhagen','Stockholm','Berlin','Prague','Vienna','Zurich','Rome','Venice','Athens','Istanbul','Marrakesh','Cairo','Nairobi','Cape Town','Dubai','Doha','Mumbai','Delhi','Jaipur','Bangkok','Hanoi','Bali','Singapore','Hong Kong','Shanghai','Beijing','Taipei','Seoul','Kyoto','Tokyo','Sydney','Melbourne','Auckland','Honolulu','Vancouver','San Francisco','Los Angeles','Chicago','Toronto','New York','Miami','Mexico City','Havana','Lima','Rio','Buenos Aires']}};
function boardFor(key){const m=maps[key];let city=0;return Array.from({length:m.size},(_,i)=>{const q=m.size/4;let type=i===0?'go':i===q?'jail':i===q*2?'park':i===q*3?'gojail':i%q===Math.floor(q/2)?'station':i%9===3?'event':i%13===4?'tax':'property';return {id:i,type,name:type==='property'?m.cities[city++%m.cities.length]:({go:'Departure',jail:'Jail / visiting',park:'City park',gojail:'Go to jail',station:'Airport',event:'City event',tax:'City tax'})[type],group:Math.floor(i/4),price:100+Math.floor(i/4)*35,rent:12+Math.floor(i/4)*5};});}
function createGame(map='world',rules={}){if(!maps[map])throw Error('Unknown map');return {map,rules:{salary:200,startCash:2000,events:true,freeParking:false,roundLimit:0,...rules},players:[],status:'lobby',turn:0,phase:'roll',round:1,dice:[1,1],doubles:0,properties:{},log:['Room created. Invite your friends.'],pot:0,pending:null,trade:null};}
function log(g,s){g.log.unshift(s);g.log=g.log.slice(0,40);}
function requireThat(c,s){if(!c)throw Error(s);}
function pay(g,p,amount,to){p.cash-=amount;if(to)to.cash+=amount;else g.pot+=amount;}
function finish(g){const alive=g.players.filter(x=>!x.out);if(alive.length===1){g.status='finished';g.winner=alive[0].id;log(g,alive[0].name+' wins!');}}
function act(g,id,a,random=()=>{const n=new Uint32Array(1);crypto.getRandomValues(n);return n[0]/4294967296;}){const p=g.players.find(x=>x.id===id);requireThat(p,'Join this room first');const board=boardFor(g.map);const current=g.players[g.turn];const own=(i)=>g.properties[i];const full=(group)=>board.filter(t=>t.type==='property'&&t.group===group).every(t=>own(t.id)?.owner===id);const add=(s)=>log(g,s);
if(a.type==='start'){requireThat(p.id===g.players[0].id,'Only the host can start');requireThat(g.status==='lobby'&&g.players.length>=2,'Need at least two players');g.status='playing';g.players.forEach(x=>x.cash=g.rules.startCash);add('The game begins. '+current.name+' rolls first.');return;}
requireThat(g.status==='playing'&&!p.out,'Game is not active');
if(a.type==='trade'){requireThat(!g.trade,'Resolve the existing offer');const target=g.players.find(x=>x.id===a.target&&!x.out&&x.id!==id);requireThat(target,'Choose another player');const give=Number(a.giveCash),take=Number(a.takeCash);requireThat(Number.isInteger(give)&&give>=0&&give<=p.cash&&Number.isInteger(take)&&take>=0&&take<=target.cash,'Invalid cash offer');const gp=Number(a.giveProperty),tp=Number(a.takeProperty);requireThat((gp===-1||own(gp)?.owner===id&&!own(gp).level)&&(tp===-1||own(tp)?.owner===target.id&&!own(tp).level),'Only undeveloped owned properties can be traded');g.trade={from:id,to:target.id,give,take,gp,tp};add(p.name+' proposed a trade.');return;}
if(a.type==='rejectTrade'){requireThat(g.trade&&(g.trade.to===id||g.trade.from===id),'No offer');g.trade=null;return;}
if(a.type==='acceptTrade'){const t=g.trade;requireThat(t?.to===id,'No trade for you');const from=g.players.find(x=>x.id===t.from);requireThat(from.cash>=t.give&&p.cash>=t.take&&(t.gp===-1||own(t.gp)?.owner===from.id)&&(t.tp===-1||own(t.tp)?.owner===id),'Offer no longer valid');from.cash+=t.take-t.give;p.cash+=t.give-t.take;if(t.gp!==-1)own(t.gp).owner=id;if(t.tp!==-1)own(t.tp).owner=from.id;g.trade=null;add('Trade completed.');return;}
requireThat(current.id===id,'Wait for your turn');
if(a.type==='build'){const t=board[Number(a.tile)],o=own(t?.id);requireThat(t?.type==='property'&&o?.owner===id&&full(t.group)&&!board.some(x=>x.group===t.group&&own(x.id)?.mortgaged),'Own an unmortgaged city set first');const level=o.level||0,cost=Math.ceil(t.price/2);requireThat(level<5&&p.cash>=cost,'Cannot afford more buildings');requireThat(board.filter(x=>x.type==='property'&&x.group===t.group).every(x=>(own(x.id).level||0)>=level),'Build evenly across the set');p.cash-=cost;o.level=level+1;add(p.name+' developed '+t.name);return;}
if(a.type==='mortgage'){const t=board[Number(a.tile)],o=own(t?.id);requireThat(o?.owner===id&&!board.some(x=>x.group===t.group&&(own(x.id)?.level||0)>0),'Sell buildings in this set first');const cost=Math.floor(t.price/2);if(o.mortgaged){requireThat(p.cash>=Math.ceil(cost*1.1),'Not enough cash');p.cash-=Math.ceil(cost*1.1);o.mortgaged=false;}else{p.cash+=cost;o.mortgaged=true;}return;}
if(a.type==='sellBuilding'){const t=board[Number(a.tile)],o=own(t?.id);requireThat(o?.owner===id&&o.level>0,'No building to sell');o.level--;p.cash+=Math.floor(t.price/4);return;}
if(a.type==='bankrupt'){requireThat(p.cash<0,'Bankruptcy requires debt');p.out=true;for(const [i,o]of Object.entries(g.properties))if(o.owner===id)delete g.properties[i];g.trade=null;add(p.name+' is bankrupt.');finish(g);if(g.status==='playing')next();return;}
if(a.type==='bail'){requireThat(p.jail>0&&g.phase==='roll'&&p.cash>=50,'Bail unavailable');p.cash-=50;p.jail=0;add(p.name+' paid bail.');return;}
if(a.type==='buy'){requireThat(g.phase==='buy','No property for sale');const t=board[p.pos];requireThat(!own(t.id)&&p.cash>=t.price,'Cannot afford this property');p.cash-=t.price;g.properties[t.id]={owner:id,level:0,mortgaged:false};g.phase='end';add(p.name+' bought '+t.name);return;}
if(a.type==='skip'){requireThat(g.phase==='buy','No purchase pending');g.phase='end';return;}
if(a.type==='end'){requireThat(g.phase==='end'&&p.cash>=0,'Resolve your turn and debts first');if(g.doubles&&p.jail===0){g.phase='roll';add(p.name+' rolls again for doubles.');}else next();return;}
requireThat(a.type==='roll'&&g.phase==='roll','Roll is unavailable');requireThat(p.cash>=0,'Resolve debts first');g.dice=[1+Math.floor(random()*6),1+Math.floor(random()*6)];const doubles=g.dice[0]===g.dice[1];g.doubles=doubles?g.doubles+1:0;g.phase='end';if(g.doubles===3){jail();return;}
if(p.jail){p.jail--;if(doubles){p.jail=0;g.doubles=0;add(p.name+' rolled out of jail.');}else if(p.jail>0){add(p.name+' stays in jail.');return;}else{pay(g,p,50);add(p.name+' paid $50 to leave jail.');}}
const old=p.pos;p.pos=(old+g.dice[0]+g.dice[1])%board.length;if(p.pos<old){p.cash+=g.rules.salary;add(p.name+' collected $'+g.rules.salary);}
const t=board[p.pos];add(p.name+' landed on '+t.name);if(t.type==='gojail'){jail();return;}if(t.type==='tax'){pay(g,p,100);add('City tax: $100');}if(t.type==='park'&&g.rules.freeParking){p.cash+=g.pot;add('Park jackpot: $'+g.pot);g.pot=0;}if(t.type==='event'&&g.rules.events){const amount=random()<.5?100:-75;p.cash+=amount;add(amount>0?'City festival bonus: $100':'Street repairs: pay $75');}
if(['property','station'].includes(t.type)){const o=own(t.id);if(!o){g.phase='buy';}else if(o.owner!==id&&!o.mortgaged){const owner=g.players.find(x=>x.id===o.owner);const level=o.level||0;const stations=board.filter(x=>x.type==='station'&&own(x.id)?.owner===owner.id).length;const rent=t.type==='station'?25*Math.pow(2,stations-1):t.rent*[1,3,8,15,25,40][level]*(level===0&&board.filter(x=>x.type==='property'&&x.group===t.group).every(x=>own(x.id)?.owner===owner.id)?2:1);pay(g,p,rent,owner);add(p.name+' paid $'+rent+' rent to '+owner.name);}}
function jail(){p.pos=board.length/4;p.jail=3;g.doubles=0;g.phase='end';add(p.name+' went to jail.');}
function next(){g.doubles=0;g.trade=null;let next=g.turn;do{next=(next+1)%g.players.length;if(next===0)g.round++;}while(g.players[next].out);g.turn=next;g.phase='roll';if(g.rules.roundLimit&&g.round>g.rules.roundLimit){g.status='finished';g.winner=g.players.filter(x=>!x.out).sort((a,b)=>worth(b)-worth(a))[0].id;add('Round limit reached. Highest net worth wins.');}}
function worth(x){return x.cash+Object.entries(g.properties).filter(([,o])=>o.owner===x.id).reduce((sum,[i,o])=>sum+board[i].price*(o.mortgaged?.5:1)+(o.level||0)*Math.ceil(board[i].price/2),0);}
}

const page="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>Freeboard — cities without limits</title><style>\n*{box-sizing:border-box}body{margin:0;background:#172c3d;color:#f2f7fc;font-family:system-ui,sans-serif}button,input,select{font:inherit}button{cursor:pointer;border:0;border-radius:7px;padding:11px 15px;background:#32c3ab;color:#052d30;font-weight:700}button:disabled{opacity:.35;cursor:default}button.secondary{background:#304b62;color:white}input,select{width:100%;border:1px solid #486076;background:#14283a;color:white;padding:12px;border-radius:7px}label{display:block;font-size:12px;color:#b4c8d8;margin:14px 0 6px}header{height:72px;padding:0 28px;background:#102232;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #345067}header b{font-size:26px;letter-spacing:-1px;color:#5cddc2}header small{color:#a8c0d3}main{max-width:1500px;margin:auto;padding:24px}.intro{text-align:center;padding:35px 0 22px}.intro h1{font-size:48px;letter-spacing:-2px;margin:0 0 10px}.intro p{color:#a8c0d3;margin:0}.lobby{display:grid;grid-template-columns:1fr 1fr;gap:22px;max-width:860px;margin:15px auto}.panel{background:#203b50;border:1px solid #36566c;border-radius:14px;padding:22px;box-shadow:0 8px 24px #0002}.panel h2{font-size:19px;margin:0 0 10px}.row{display:flex;gap:10px;align-items:center;flex-wrap:wrap}.row>*{flex:1}.check{display:flex;gap:8px;align-items:center}.check input{width:auto}.full{width:100%;margin-top:20px}.map-card{border:1px solid #466173;padding:14px;border-radius:8px;margin-top:12px;background:#183044}.map-card b{display:block;color:#62dcc6}.map-card small{color:#b4c8d8}.error{color:#ffd098;min-height:24px;text-align:center;margin:10px}.hidden{display:none!important}.game{display:grid;grid-template-columns:minmax(500px,1fr) 330px;gap:20px}.board-wrap{background:#102635;padding:12px;border-radius:12px;border:1px solid #385b6e}.board{display:grid;aspect-ratio:1;gap:3px;background:#335567;padding:3px;border-radius:7px}.tile{background:#dfeadf;color:#163340;position:relative;font-size:clamp(7px,.8vw,12px);padding:5px 3px;display:flex;flex-direction:column;justify-content:space-between;align-items:center;text-align:center;border-radius:3px;min-width:0;overflow:hidden;border:2px solid transparent;cursor:pointer}.tile .band{height:9px;width:calc(100% + 6px);margin:-5px -3px 3px}.tile b{font-size:inherit;overflow-wrap:anywhere}.tile em{font-style:normal;font-size:9px}.tile.special{background:#bee0d4}.tile.selected{border-color:#fff;box-shadow:inset 0 0 0 2px #17374b}.tokens{display:flex;justify-content:center;gap:2px;min-height:13px;flex-wrap:wrap}.token{width:12px;height:12px;border-radius:50%;border:1px solid white;box-shadow:0 1px 3px #0009}.center{background:radial-gradient(ellipse,#315b63,#234d55);display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:16px;min-width:0}.center h1{font-size:clamp(20px,4vw,55px);margin:0;color:#d8f3d8;letter-spacing:-2px}.center p{color:#a7d7cc;font-size:12px}.center .dice{font-size:35px;color:#fff;margin:10px}.center .turn{background:#173e48;border:1px solid #638d8e;border-radius:20px;padding:7px 16px}.sidebar{display:grid;gap:12px;align-content:start}.sidebar .panel{padding:16px}.players{display:grid;gap:8px;margin-top:12px}.player{display:flex;align-items:center;gap:9px;padding:10px;border-radius:8px;background:#183044;font-size:13px}.player.active{outline:1px solid #6addc2}.player .amount{margin-left:auto;font-weight:800}.player.out{opacity:.4}.logs{max-height:170px;overflow:auto;font-size:12px;color:#bed1de;line-height:1.6}.logs div{border-bottom:1px solid #365468;padding:5px 0}.actions{display:flex;flex-wrap:wrap;gap:7px;margin-top:10px}.actions button{flex:1;font-size:12px}.property{font-size:13px;color:#c8dce5;line-height:1.8}.code{font-family:monospace;letter-spacing:2px;color:#63e0c6;font-size:22px}.small{font-size:12px;color:#a8c0d3}.portfolio{display:flex;gap:5px;flex-wrap:wrap;margin-top:8px}.chip{font-size:10px;padding:5px;border-radius:5px;background:#173044;color:#daecee}.trade-form{display:grid;gap:8px}.trade-form select,.trade-form input{padding:7px;font-size:12px}details summary{cursor:pointer;font-size:13px}footer{text-align:center;color:#93afc1;font-size:11px;margin:25px} @media(max-width:900px){.game{grid-template-columns:1fr}.sidebar{grid-template-columns:1fr 1fr}.lobby{grid-template-columns:1fr}.intro h1{font-size:34px}main{padding:10px}}@media(max-width:550px){.sidebar{grid-template-columns:1fr}.board-wrap{padding:3px}.board{gap:1px;padding:1px}.tile{font-size:6px;padding:2px 0}.tile .band{height:5px}.tile em{font-size:6px}.token{width:7px;height:7px}.tokens{min-height:7px}.center{padding:4px}.center h1{letter-spacing:-1px}.center p{font-size:9px}.center .dice{font-size:24px}header{padding:0 14px}header small{font-size:10px}}\n</style></head><body><header><b>◈ freeboard</b><small>YOUR FRIENDS. YOUR CITIES. YOUR RULES.</small></header><main><div id=\"home\"><section class=\"intro\"><h1>A world worth owning.</h1><p>Invite your friends. Buy cities. Build an empire. Every map is free.</p></section><div class=\"lobby\"><section class=\"panel\"><h2>Create a private table</h2><label for=\"name\">Your name</label><input id=\"name\" maxlength=\"24\" placeholder=\"Enter your name\"><label for=\"map\">Choose your world</label><select id=\"map\"><option value=\"world\">World Tour · 40 spaces</option><option value=\"europe\">Grand Europe · 48 spaces</option><option value=\"mega\">Global Empire · 64 spaces</option></select><div class=\"map-card\"><b id=\"map-title\">From Dublin to Tokyo</b><small>2–8 friends · city sets · airports · events · trading</small></div><div class=\"row\"><div><label>Starting cash</label><select id=\"cash\"><option>1500</option><option selected>2000</option><option>3000</option></select></div><div><label>Salary per lap</label><select id=\"salary\"><option>200</option><option>300</option><option>500</option></select></div><div><label>Round limit</label><select id=\"limit\"><option value=\"0\">No limit</option><option>20</option><option>40</option><option>60</option></select></div></div><label class=\"check\"><input type=\"checkbox\" id=\"events\" checked> City events</label><label class=\"check\"><input type=\"checkbox\" id=\"parking\"> Tax-funded park jackpot</label><button class=\"full\" id=\"create\">Create room →</button></section><section class=\"panel\"><h2>Join your friends</h2><p class=\"small\">Get the room code or invitation link from your host. No account needed.</p><label for=\"joinname\">Your name</label><input id=\"joinname\" maxlength=\"24\" placeholder=\"Enter your name\"><label for=\"code\">Room code</label><input id=\"code\" maxlength=\"8\" placeholder=\"ABCD2345\" style=\"text-transform:uppercase\"><button class=\"full\" id=\"join\">Join table →</button><div class=\"map-card\"><b>How to play</b><small>Roll to move. Buy unowned cities and collect rent. Own a full color set to build houses and hotels. Trade, mortgage, and outlast your friends.</small></div><div id=\"resume\"></div></section></div></div><p id=\"error\" class=\"error\" role=\"status\"></p><div id=\"room\" class=\"hidden\"><div class=\"row\" style=\"margin:10px 0 18px\"><div><span class=\"small\">PRIVATE TABLE / </span><span class=\"code\" id=\"roomcode\"></span></div><div style=\"text-align:right\"><button class=\"secondary\" id=\"invite\">Copy invite link</button> <button class=\"secondary\" id=\"leave\">Leave view</button></div></div><div class=\"game\"><div class=\"board-wrap\"><div id=\"board\" class=\"board\"></div></div><aside class=\"sidebar\"><section class=\"panel\"><h2 id=\"game-title\"></h2><p class=\"small\" id=\"phase\"></p><div id=\"controls\" class=\"actions\"></div><div id=\"players\" class=\"players\"></div></section><section class=\"panel\"><h2 id=\"property-title\">Explore the board</h2><div id=\"property\" class=\"property\">Select a city to see its price, rent, owner and development.</div><div id=\"property-actions\" class=\"actions\"></div></section><section class=\"panel\"><details><summary>Propose a trade</summary><div class=\"trade-form\"><label>Trade with</label><select id=\"target\"></select><label>You offer / request cash</label><div class=\"row\"><input id=\"giveCash\" type=\"number\" min=\"0\" value=\"0\" aria-label=\"Cash offered\"><input id=\"takeCash\" type=\"number\" min=\"0\" value=\"0\" aria-label=\"Cash requested\"></div><label>Your city / their city</label><select id=\"giveProp\"></select><select id=\"takeProp\"></select><button id=\"offer\">Send offer</button></div></details><div id=\"trade\"></div></section><section class=\"panel\"><h2>Table activity</h2><div class=\"logs\" id=\"logs\"></div></section></aside></div></div></main><footer>Freeboard · independent property trading game · room state saves automatically · keep your room link to return</footer><script>\nconst $=id=>document.getElementById(id),colors=['#e17c65','#8d8fd8','#60baba','#dcab4d','#79b85d','#d56c9d','#5e9fd1','#bda16e','#9c83c8','#d7ad7f','#bace5b','#70c7c0','#a79bc3','#df9d67','#74b8db','#e2819a'];let session=null,data=null,selected=null,busy=false,polling=false;try{session=JSON.parse(localStorage.getItem('freeboard-session'));}catch{}const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));const money=n=>'$'+n.toLocaleString();\nasync function api(path,body){const r=await fetch('/api/'+path,{method:body?'POST':'GET',headers:{'Content-Type':'application/json',...(session?{Authorization:'Bearer '+session.token}:{})},...(body?{body:JSON.stringify(body)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d;}\nfunction error(e){$('error').textContent=e.message||e;}async function enter(s){session=s;localStorage.setItem('freeboard-session',JSON.stringify(s));await refresh();}async function refresh(){if(!session||polling)return;polling=true;try{data=await api('state?code='+session.code);$('home').classList.add('hidden');$('room').classList.remove('hidden');render();}catch(e){error(e);}finally{polling=false;}}\nasync function action(type,extra={}){if(busy)return;busy=true;try{$('error').textContent='';data=await api('action',{...session,action:{type,...extra}});render();}catch(e){error(e);await refresh();}finally{busy=false;}}\n$('create').onclick=async()=>{if(busy)return;busy=true;try{const s=await api('create',{name:$('name').value,map:$('map').value,rules:{startCash:+$('cash').value,salary:+$('salary').value,roundLimit:+$('limit').value,events:$('events').checked,freeParking:$('parking').checked}});await enter(s);}catch(e){error(e);}finally{busy=false;}};\n$('join').onclick=async()=>{try{await enter(await api('join',{code:$('code').value.trim(),name:$('joinname').value,...(session?{token:session.token}:{})}));}catch(e){error(e);}};\n$('invite').onclick=async()=>{try{await navigator.clipboard.writeText(location.origin+'/?room='+session.code);$('invite').textContent='Link copied!';setTimeout(()=>$('invite').textContent='Copy invite link',2000);}catch{error('Invite: '+location.origin+'/?room='+session.code);}};\n$('leave').onclick=()=>{session=null;data=null;$('room').classList.add('hidden');$('home').classList.remove('hidden');};\nfunction btn(label,type,disabled=false,extra={}){const b=document.createElement('button');b.textContent=label;b.disabled=disabled;b.onclick=()=>action(type,extra);return b;}\nfunction render(){const {game:g,me,board:b}=data,p=g.players.find(x=>x.id===me),current=g.players[g.turn],mine=current.id===me,active=g.status==='playing';$('roomcode').textContent=session.code;$('game-title').textContent=data.maps[g.map].name;$('phase').textContent=g.status==='lobby'?'Waiting for friends · '+g.players.length+'/8 joined':g.status==='finished'?'Winner: '+g.players.find(x=>x.id===g.winner)?.name:'Round '+g.round+' · '+current.name+'’s turn'+(p.jail?' · jailed for '+p.jail+' turns':'');\nconst controls=$('controls');controls.replaceChildren();if(g.status==='lobby')controls.append(btn('Start game', 'start',g.players[0].id!==me||g.players.length<2));if(active){controls.append(btn('Roll dice','roll',!mine||g.phase!=='roll'||p.cash<0));if(mine&&g.phase==='buy'){controls.append(btn('Buy '+money(b[p.pos].price),'buy',p.cash<b[p.pos].price),btn('Pass','skip'));}if(mine&&g.phase==='end')controls.append(btn('End turn →','end',p.cash<0));if(mine&&p.jail&&g.phase==='roll')controls.append(btn('Pay $50 bail','bail',p.cash<50));if(mine&&p.cash<0)controls.append(btn('Declare bankruptcy','bankrupt'));}\n$('players').innerHTML=g.players.map((x,i)=>'<div class=\"player '+(current.id===x.id?'active ':'')+(x.out?'out':'')+'\"><span class=\"token\" style=\"background:'+colors[i]+'\"></span><span>'+esc(x.name)+(x.id===me?' (you)':'')+(x.out?' · bankrupt':'')+'<br><small>'+Object.values(g.properties).filter(o=>o.owner===x.id).length+' properties</small></span><span class=\"amount\">'+money(x.cash)+'</span></div>').join('');\nconst side=b.length/4+1,board=$('board');board.style.gridTemplateColumns='repeat('+side+',1fr)';board.style.gridTemplateRows='repeat('+side+',1fr)';board.innerHTML='';b.forEach((t,i)=>{const q=side-1;let r,c;if(i<q){r=side;c=side-i;}else if(i<q*2){r=side-(i-q);c=1;}else if(i<q*3){r=1;c=1+i-q*2;}else{r=1+i-q*3;c=side;}const el=document.createElement('div'),o=g.properties[i];el.className='tile '+(t.type!=='property'?'special ':'')+(selected===i?'selected':'');el.style.gridArea=r+' / '+c;if(o)el.style.borderColor=colors[g.players.findIndex(x=>x.id===o.owner)];el.innerHTML=(t.type==='property'?'<div class=\"band\" style=\"background:'+colors[t.group%colors.length]+'\"></div>':'')+'<b>'+esc(t.name)+'</b><em>'+(o?.mortgaged?'MORTGAGED':o?.level===5?'🏨':o?.level?'⌂'.repeat(o.level):['property','station'].includes(t.type)?money(t.price):({go:'↻ +'+money(g.rules.salary),event:'✦',station:'✈',jail:'▦',gojail:'→ ▦',park:'♧',tax:'−$100'})[t.type])+'</em><div class=\"tokens\">'+g.players.filter(x=>x.pos===i&&!x.out).map(x=>'<span class=\"token\" title=\"'+esc(x.name)+'\" style=\"background:'+colors[g.players.indexOf(x)]+'\"></span>').join('')+'</div>';el.onclick=()=>{selected=i;render();};board.append(el);});const center=document.createElement('div');center.className='center';center.style.gridArea='2 / 2 / '+side+' / '+side;center.innerHTML='<h1>freeboard</h1><p>'+esc(data.maps[g.map].name)+' / '+b.length+' spaces</p><div class=\"dice\">'+['⚀','⚁','⚂','⚃','⚄','⚅'][g.dice[0]-1]+' '+['⚀','⚁','⚂','⚃','⚄','⚅'][g.dice[1]-1]+'</div><div class=\"turn\">'+esc(g.status==='lobby'?'Invite your friends':current.name+'’s turn')+'</div><p>'+(g.rules.freeParking?'Park jackpot '+money(g.pot):'Buy. Build. Trade. Repeat.')+'</p>';board.append(center);\nconst t=b[selected],o=g.properties[selected];$('property-actions').replaceChildren();if(t){$('property-title').textContent=t.name;$('property').innerHTML=['property','station'].includes(t.type)?'Price '+money(t.price)+' · base rent '+money(t.rent)+'<br>Owner: '+esc(o?g.players.find(x=>x.id===o.owner).name:'Bank')+'<br>Buildings: '+(o?.level||0)+' / 5'+(o?.mortgaged?' · mortgaged':''):'Special space · '+esc(t.type);if(active&&mine&&o?.owner===me){$('property-actions').append(btn('Build '+money(Math.ceil(t.price/2)),'build',false,{tile:t.id}),btn(o.mortgaged?'Redeem':'Mortgage','mortgage',false,{tile:t.id}));if(o.level)$('property-actions').append(btn('Sell building','sellBuilding',false,{tile:t.id}));}}\n$('logs').innerHTML=g.log.map(x=>'<div>'+esc(x)+'</div>').join('');const old=$('target').value;$('target').innerHTML=g.players.filter(x=>x.id!==me&&!x.out).map(x=>'<option value=\"'+x.id+'\">'+esc(x.name)+'</option>').join('');if(g.players.some(x=>x.id===old))$('target').value=old;updateProps();$('trade').replaceChildren();if(g.trade){const t=g.trade,offer=document.createElement('p');offer.className='small';offer.textContent=g.players.find(x=>x.id===t.from).name+' offers '+money(t.give)+(t.gp>=0?' + '+b[t.gp].name:'')+' for '+money(t.take)+(t.tp>=0?' + '+b[t.tp].name:'');$('trade').append(offer);if(t.to===me)$('trade').append(btn('Accept','acceptTrade'),btn('Decline','rejectTrade'));if(t.from===me)$('trade').append(btn('Cancel offer','rejectTrade'));}}\nfunction updateProps(){if(!data)return;const {game:g,me,board:b}=data;for(const [field,owner]of [['giveProp',me],['takeProp',$('target').value]]){const old=$(field).value;$(field).innerHTML='<option value=\"-1\">No property</option>'+b.filter(t=>g.properties[t.id]?.owner===owner&&!g.properties[t.id].level).map(t=>'<option value=\"'+t.id+'\">'+esc(t.name)+'</option>').join('');if([...$(field).options].some(o=>o.value===old))$(field).value=old;}}\n$('target').onchange=updateProps;$('offer').onclick=()=>action('trade',{target:$('target').value,giveCash:+$('giveCash').value,takeCash:+$('takeCash').value,giveProperty:+$('giveProp').value,takeProperty:+$('takeProp').value});$('map').onchange=()=>{$('map-title').textContent={world:'From Dublin to Tokyo',europe:'48 spaces across Europe',mega:'64 spaces. One global empire.'}[$('map').value];};const requested=new URLSearchParams(location.search).get('room');if(requested){$('code').value=requested;if(session?.code===requested)refresh();}else if(session){const b=document.createElement('button');b.className='full secondary';b.textContent='Return to '+session.code;b.onclick=refresh;$('resume').append(b);}setInterval(()=>{if(!$('room').classList.contains('hidden')&&!busy)refresh();},1500);\n</script></body></html>\n";
const response=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
export default {async fetch(req,env){const url=new URL(req.url);if(!url.pathname.startsWith('/api/'))return new Response(page,{headers:{'Content-Type':'text/html; charset=utf-8'}});try{
if(url.pathname==='/api/health')return response({ok:true});
const db=env.DB;const body=req.method==='POST'?await req.json():{};const code=(body.code||url.searchParams.get('code')||'').toUpperCase();
if(url.pathname==='/api/create'){const g=createGame(body.map,body.rules);const token=crypto.randomUUID();const name=String(body.name||'Host').trim().slice(0,24)||'Host';g.players.push({id:crypto.randomUUID(),token,name,pos:0,cash:g.rules.startCash,jail:0,out:false});const bytes=new Uint8Array(8);crypto.getRandomValues(bytes);const room=Array.from(bytes,x=>'ABCDEFGHJKLMNPQRSTUVWXYZ23456789'[x%32]).join('');await db.prepare('INSERT INTO rooms (code,state,revision,updated) VALUES (?,?,0,?)').bind(room,JSON.stringify(g),Date.now()).run();return response({code:room,token});}
if(!/^[A-Z2-9]{8}$/.test(code))throw Error('Enter the eight-character room code');
const row=await db.prepare('SELECT state,revision FROM rooms WHERE code=?').bind(code).first();if(!row) return response({error:'Room not found'},404);const g=JSON.parse(row.state);const token=body.token||req.headers.get('Authorization')?.replace('Bearer ','');let player=g.players.find(x=>x.token===token);
if(url.pathname==='/api/join'){if(player)return response({code,token});if(g.status!=='lobby')throw Error('This game has already started');if(g.players.length>=8)throw Error('Room is full');const t=crypto.randomUUID();g.players.push({id:crypto.randomUUID(),token:t,name:String(body.name||'Player').trim().slice(0,24)||'Player',pos:0,cash:g.rules.startCash,jail:0,out:false});await save(t);return response({code,token:t});}
if(!player)return response({error:'Join the room to play'},401);
if(url.pathname==='/api/action'){act(g,player.id,body.action);await save();}else if(url.pathname!=='/api/state')return response({error:'Not found'},404);
return response({game:{...g,players:g.players.map(({token,...p})=>p)},me:player.id,board:boardFor(g.map),maps,revision:row.revision});
async function save(){const r=await db.prepare('UPDATE rooms SET state=?,revision=revision+1,updated=? WHERE code=? AND revision=?').bind(JSON.stringify(g),Date.now(),code,row.revision).run();if(!r.meta.changes)throw Error('Room changed — try again');}
}catch(e){return response({error:e.message||'Request failed'},400);}}};
